linkedIssues.body:
Given a .env with only one line:
`FOO = "\\"`

godotenv.Read(".env") will return an error because the ``prevChar == '\\'``, even though it's escaped.

```
// lookup quoted string terminator
for i := 1; i < len(src); i++ {
	if char := src[i]; char != quote {
		continue
	}

	// skip escaped quote symbol (\" or \', depends on quote)
	if prevChar := src[i-1]; prevChar == '\\' {
		continue
	}

	// trim quotes
	trimFunc := isCharFunc(rune(quote))
	value = string(bytes.TrimLeftFunc(bytes.TrimRightFunc(src[0:i], trimFunc), trimFunc))
	if quote == prefixDoubleQuote {
		// unescape newlines for double quote (this is compat feature)
		// and expand environment variables
		value = expandVariables(expandEscapes(value), vars)
	}

	return value, src[i+1:], nil
}
```

extractVarValue should instead check whether the quote symbol is preceded by an odd number of backslashes (escaped) or an even number (not escaped).

diff:
diff --git a/godotenv_test.go b/godotenv_test.go
index 96fde99..9e111a9 100644
--- a/godotenv_test.go
+++ b/godotenv_test.go
@@ -342,6 +342,9 @@ func TestParsing(t *testing.T) {
 	// parses escaped double quotes
 	parseAndCompare(t, `FOO="escaped\"bar"`, "FOO", `escaped"bar`)

+	// a trailing escaped backslash does not escape the closing quote
+	parseAndCompare(t, `FOO="bar\\"`, "FOO", `bar\`)
+
 	// parses single quotes inside double quotes
 	parseAndCompare(t, `FOO="'d'"`, "FOO", `'d'`)

diff --git a/parser.go b/parser.go
index 49fc292..bf5e8f9 100644
--- a/parser.go
+++ b/parser.go
@@ -166,8 +166,12 @@ func extractVarValue(src []byte, vars map[string]string) (value string, rest []b
 			continue
 		}

-		// skip escaped quote symbol (\" or \', depends on quote)
-		if prevChar := src[i-1]; prevChar == '\\' {
+		// skip escaped quote symbol; a quote is escaped only when preceded by an odd number of backslashes
+		backslashes := 0
+		for j := i - 1; j >= 0 && src[j] == '\\'; j-- {
+			backslashes++
+		}
+		if backslashes%2 == 1 {
 			continue
 		}
